	test('whenBindReady is false when Create/Resume returns empty session_id', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		sessionView.whenEngineSessionReadyFn = async () => '';
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-empty-id'));
		assert.strictEqual(await source.whenLeaseBindReady(lease), false);
		assert.strictEqual((lease as { boundEngineSessionId?: string }).boundEngineSessionId, '');
	});

	test('getCachedProjection is undefined after bind reject even when host frames landed', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		sessionView.whenEngineSessionReady = async () => '';
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-bind-cache'));

		store.add(lease.onDidApplyFrame(() => { }));
		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.deepStrictEqual(lease.snapshot.sync, { kind: 'live' });
		assert.ok(source.getCachedProjection('sess-bind-cache'));

		assert.strictEqual(await source.whenLeaseBindReady(lease), false);
		assert.strictEqual(source.getCachedProjection('sess-bind-cache'), undefined);
	});

	test('first post after bind reject is no_such_session; second post retries and forwards', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		let failFirst = true;
		sessionView.whenEngineSessionReadyFn = async sessionId => {
			if (failFirst) {
				failFirst = false;
				throw new Error('transient bind fail');
			}
			return sessionId;
		};
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-rebind'));

		assert.deepStrictEqual(await lease.post({ kind: 'submitInput', text: 'first' }), {
			accepted: false,
			reason: 'no_such_session',
		});
		const lastPostAfterReject = sessionView.lastPost;
		assert.strictEqual(lastPostAfterReject, undefined);
		assert.deepStrictEqual(await lease.post({ kind: 'submitInput', text: 'second' }), {
			accepted: true,
			correlation: { id: 'host-corr' },
		});
		const lastPostAfterRetry = sessionView.lastPost;
		assert.strictEqual(lastPostAfterRetry?.leaseId, 'lease:sess-rebind');
		assert.deepStrictEqual(lastPostAfterRetry?.msg, { kind: 'submitInput', text: 'second' });
	});

	test('in-flight bind reuses one whenEngineSessionReady call', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		let resolveReady!: (id: string) => void;
		sessionView.whenEngineSessionReadyFn = () => new Promise<string>(resolve => {
			resolveReady = resolve;
		});
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-inflight'));

		const first = lease.post({ kind: 'submitInput', text: 'a' });
		const second = lease.post({ kind: 'submitInput', text: 'b' });
		for (let i = 0; i < 20 && sessionView.whenEngineSessionReadyCalls === 0; i++) {
			await new Promise<void>(resolve => queueMicrotask(() => resolve()));
		}
		assert.strictEqual(sessionView.whenEngineSessionReadyCalls, 1);
		resolveReady('engine-sess-inflight');
		assert.deepStrictEqual(await first, { accepted: true, correlation: { id: 'host-corr' } });
		assert.deepStrictEqual(await second, { accepted: true, correlation: { id: 'host-corr' } });
		assert.strictEqual(sessionView.whenEngineSessionReadyCalls, 1);
	});

	test('acquireLease failure is no_such_session, not silent accepted', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		sessionView.acquireLeaseFn = async () => {
			throw new Error('acquire failed');
		};
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-e'));

		assert.deepStrictEqual(await lease.post({ kind: 'submitInput', text: 'nope' }), {
			accepted: false,
			reason: 'no_such_session',
		});
		assert.strictEqual(sessionView.lastPost, undefined);
	});
});

suite('ConversationEngineFrameSource per-lease subscribe (F1)', () => {

	const store = ensureNoDisposablesAreLeakedInTestSuite();

	async function assertWarnThenRethrowDoesNotLeak(paintBoom: Error, run: () => void | Promise<void>): Promise<void> {
		// acknowledge() is async. A lone `.catch(onUnexpectedError)` still leaks
		// when the handler warn-then-rethrows.
		const unexpectedWarns: unknown[] = [];
		const unhandledRejections: unknown[] = [];
		const onUnhandledRejection = (reason: unknown) => unhandledRejections.push(reason);
		process.on('unhandledRejection', onUnhandledRejection);
		const originalErrorHandler = errorHandler.getUnexpectedErrorHandler();
		setUnexpectedErrorHandler(error => {
			unexpectedWarns.push(error);
			if (unexpectedWarns.length === 1) {
				throw error;
			}
		});
		try {
			await run();
			await timeout(0);
			await new Promise<void>(resolve => queueMicrotask(() => resolve()));
			await new Promise<void>(resolve => setImmediate(() => resolve()));
			assert.deepStrictEqual({ unhandledRejections, unexpectedWarns }, {
				unhandledRejections: [],
				unexpectedWarns: [paintBoom, paintBoom],
			});
		} finally {
			setUnexpectedErrorHandler(originalErrorHandler);
			process.off('unhandledRejection', onUnhandledRejection);
		}
	}

	test('receives pre-resolve burst after acquireLease resolves', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-timing'));

		const applied: ConversationViewFrameApplied[] = [];
		store.add(lease.onDidApplyFrame(e => applied.push(e)));

		await new Promise<void>(resolve => setTimeout(resolve, 0));

		assert.ok(applied.length >= 2);
		assert.strictEqual(applied[0]!.kind, 'baseline');
		assert.strictEqual(applied[1]!.kind, 'patches');
	});

	test('dispose before acquireLease resolves still releases the host lease', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		let resolveAcquire!: (id: string) => void;
		sessionView.acquireLeaseFn = () => new Promise<string>(resolve => {
			resolveAcquire = resolve;
		});
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = source.acquire('sess-early-dispose');
		lease.dispose();
		resolveAcquire('lease:sess-early-dispose');
		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.deepStrictEqual(sessionView.releaseLeaseCalls, ['lease:sess-early-dispose']);
		assert.strictEqual(source.getCachedProjection('sess-early-dispose'), undefined);
	});

	test('dispose releases lease after unsubscribing', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-dispose'));

		await new Promise<void>(resolve => setTimeout(resolve, 0));
		lease.dispose();

		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.deepStrictEqual(sessionView.releaseLeaseCalls, ['lease:sess-dispose']);
	});

	test('onHostFrame after dispose does not repaint or acknowledge', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-disposed-frame'));

		const applied: ConversationViewFrameApplied[] = [];
		store.add(lease.onDidApplyFrame(e => applied.push(e)));
		await new Promise<void>(resolve => setTimeout(resolve, 0));

		const appliedBefore = applied.length;
		const ackBefore = sessionView.acknowledgeCalls.length;
		const syncBefore = lease.snapshot.sync;
		lease.dispose();

		const frame: ConversationViewFrame = {
			frame: {
				leaseId: 'lease:sess-disposed-frame' as ViewLeaseId,
				generation: 1,
				frameId: 3,
				version: 3,
				body: { kind: 'patches', patches: [{ op: 'setSyncChrome', sync: { kind: 'closed', reason: 'late' } }] },
			},
		};
		(lease as unknown as {
			onHostFrame(frame: ConversationViewFrame, applied: ConversationViewFrameApplied): void;
		}).onHostFrame(frame, {
			kind: 'patches',
			changedIds: new Set(['late']),
		});
		await new Promise<void>(resolve => queueMicrotask(() => resolve()));

		assert.strictEqual(applied.length, appliedBefore);
		assert.strictEqual(sessionView.acknowledgeCalls.length, ackBefore);
		assert.deepStrictEqual(lease.snapshot.sync, syncBefore);
	});

	test('successful apply acknowledges with cursor generation/frameId/version', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-ack'));

		store.add(lease.onDidApplyFrame(() => { }));
		await new Promise<void>(resolve => setTimeout(resolve, 0));

		assert.ok(sessionView.acknowledgeCalls.length >= 2);
		assert.deepStrictEqual(sessionView.acknowledgeCalls[0], {
			leaseId: 'lease:sess-ack',
			generation: 1,
			frameId: 1,
			appliedVersion: 1,
		});
		assert.deepStrictEqual(sessionView.acknowledgeCalls[1], {
			leaseId: 'lease:sess-ack',
			generation: 1,
			frameId: 2,
			appliedVersion: 2,
		});
	});

	test('requestResync reject does not leave an unhandled rejection or apply a bad frame', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		sessionView.requestResyncFn = () => Promise.reject('boom');
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-resync-reject'));

		const applied: ConversationViewFrameApplied[] = [];
		store.add(lease.onDidApplyFrame(e => applied.push(e)));
		await new Promise<void>(resolve => setTimeout(resolve, 0));

		const appliedBefore = applied.length;
		const ackBefore = sessionView.acknowledgeCalls.length;
		const snapshotBefore = lease.snapshot;
		const unhandledRejections: unknown[] = [];
		const onUnhandledRejection = (reason: unknown) => unhandledRejections.push(reason);
		process.on('unhandledRejection', onUnhandledRejection);
		try {
			const frame: ConversationViewFrame = {
				frame: {
					leaseId: 'lease:sess-resync-reject' as ViewLeaseId,
					generation: 1,
					frameId: 99,
					version: 99,
					body: { kind: 'patches', patches: [{ op: 'setSyncChrome', sync: { kind: 'closed', reason: 'bad' } }] },
				},
			};
			(lease as unknown as {
				onHostFrame(frame: ConversationViewFrame, applied: ConversationViewFrameApplied): void;
			}).onHostFrame(frame, {
				kind: 'patches',
				changedIds: new Set(['should-not-apply']),
			});
			await new Promise<void>(resolve => queueMicrotask(() => resolve()));
			await new Promise<void>(resolve => setImmediate(() => resolve()));
			assert.deepStrictEqual(sessionView.requestResyncCalls, ['lease:sess-resync-reject']);
			assert.deepStrictEqual(unhandledRejections, []);
			assert.strictEqual(applied.length, appliedBefore);
