		}
	});

	test('releaseLease reject on dispose-after still runs onRelease/cache and does not leave an unhandled rejection', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		sessionView.releaseLeaseFn = () => Promise.reject('boom');
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-dispose-reject'));
		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.ok(source.getCachedProjection('sess-dispose-reject'));
		const unhandledRejections: unknown[] = [];
		const onUnhandledRejection = (reason: unknown) => unhandledRejections.push(reason);
		process.on('unhandledRejection', onUnhandledRejection);
		try {
			lease.dispose();
			await new Promise<void>(resolve => setTimeout(resolve, 0));
			await new Promise<void>(resolve => queueMicrotask(() => resolve()));
			await new Promise<void>(resolve => setImmediate(() => resolve()));
			assert.deepStrictEqual(sessionView.releaseLeaseCalls, ['lease:sess-dispose-reject']);
			assert.strictEqual(source.getCachedProjection('sess-dispose-reject'), undefined);
			assert.deepStrictEqual(unhandledRejections, []);
		} finally {
			process.off('unhandledRejection', onUnhandledRejection);
		}
	});

	test('onHostFrame normalizes IPC-deserialized changedIds before emit', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const lease = store.add(source.acquire('sess-ipc-normalize'));

		const applied: ConversationViewFrameApplied[] = [];
		store.add(lease.onDidApplyFrame(e => applied.push(e)));

		await new Promise<void>(resolve => setTimeout(resolve, 0));

		const frame: ConversationViewFrame = {
			frame: {
				leaseId: 'lease:sess-ipc-normalize' as ViewLeaseId,
				generation: 1,
				frameId: 3,
				version: 3,
				body: { kind: 'patches', patches: [{ op: 'setSyncChrome', sync: { kind: 'live' } }] },
			},
		};
		(lease as unknown as {
			onHostFrame(frame: ConversationViewFrame, applied: ConversationViewFrameApplied): void;
		}).onHostFrame(frame, {
			kind: 'patches',
			changedIds: { 'turn-1': true } as unknown as ReadonlySet<string>,
		});

		const patchFrame = applied.at(-1);
		assert.strictEqual(patchFrame?.kind, 'patches');
		if (patchFrame?.kind === 'patches') {
			assert.ok(patchFrame.changedIds instanceof Set);
			assert.deepStrictEqual([...patchFrame.changedIds], ['turn-1']);
		}
	});
});

suite('ConversationEngineFrameSource shared host lease (F3 / D22)', () => {

	const store = ensureNoDisposablesAreLeakedInTestSuite();

	test('two acquires for the same sessionId call host acquireLease once', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const first = store.add(source.acquire('sess-shared'));
		const second = store.add(source.acquire('sess-shared'));

		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.strictEqual(sessionView.acquireLeaseCalls.length, 1);
		assert.strictEqual(sessionView.acquireLeaseCalls[0], 'sess-shared');
		assert.ok('leaseId' in first);
		assert.ok('leaseId' in second);
		assert.strictEqual((first as { leaseId: string }).leaseId, 'lease:sess-shared');
		assert.strictEqual((second as { leaseId: string }).leaseId, 'lease:sess-shared');
	});

	test('host releaseLease runs once after all consumers dispose', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const first = store.add(source.acquire('sess-shared-release'));
		const second = store.add(source.acquire('sess-shared-release'));

		store.add(first.onDidApplyFrame(() => { }));
		store.add(second.onDidApplyFrame(() => { }));
		await new Promise<void>(resolve => setTimeout(resolve, 0));

		first.dispose();
		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.deepStrictEqual(sessionView.releaseLeaseCalls, [], 'first consumer alone must not release host lease');

		second.dispose();
		await new Promise<void>(resolve => setTimeout(resolve, 0));
		assert.deepStrictEqual(sessionView.releaseLeaseCalls, ['lease:sess-shared-release']);
	});

	test('both consumers receive the same host frame burst', async () => {
		const sessionView = new BufferedMockUniverseAgentSessionView();
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const first = store.add(source.acquire('sess-shared-frames'));
		const second = store.add(source.acquire('sess-shared-frames'));

		const firstApplied: ConversationViewFrameApplied[] = [];
		const secondApplied: ConversationViewFrameApplied[] = [];
		store.add(first.onDidApplyFrame(e => firstApplied.push(e)));
		store.add(second.onDidApplyFrame(e => secondApplied.push(e)));

		await new Promise<void>(resolve => setTimeout(resolve, 0));

		assert.ok(firstApplied.length >= 2);
		assert.deepStrictEqual(firstApplied, secondApplied);
		assert.deepStrictEqual(first.snapshot.sync, second.snapshot.sync);
	});
	test('captured response completion cannot clean or fail a replacement binding with the same session and request ids', async () => {
		const sessionView = new PostOutcomeMockSessionView();
		const frames = store.add(new Emitter<IUniverseAgentSessionViewFrameEvent>());
		sessionView.onDynamicDidApplyFrame = () => frames.event;
		const source = store.add(new ConversationEngineFrameSource(sessionView));
		const snapshot: SessionViewSnapshot = {
			...emptySessionViewSnapshot('replacement' as SessionId),
			timeline: [{ id: 'same' as TimelineItemId, orderKey: 'same', summary: { kind: 'permission', title: 'Run?', permissionKind: 'shell' } }],
			pendingActions: [{ requestId: 'same' as ClientActionRequestId, summary: { kind: 'permission', title: 'Run?', permissionKind: 'shell' } }],
		};
		const baseline = () => frames.fire({ leaseId: 'lease:replacement', sessionId: 'replacement', applied: { kind: 'baseline' }, frame: { frame: {
			leaseId: 'lease:replacement' as ViewLeaseId, generation: 1, frameId: 1, version: 1, body: { kind: 'baseline', snapshot },
		} } });
		const first = store.add(source.acquire('replacement'));
		await timeout(0);
		baseline();
		const old = source.beginResponse('replacement', 'permission', 'same');
		assert.strictEqual(old.kind, 'started');
		if (old.kind !== 'started') { return; }
		first.dispose();
		const replacement = store.add(source.acquire('replacement'));
		await timeout(0);
		baseline();
		const before = JSON.stringify(replacement.snapshot);
		old.complete({ retryable: true, error: 'late failure' });
		old.complete(undefined, view => permissionRespondCleanupPatches(view, { requestId: 'same', decision: 'allow' }));
		assert.strictEqual(old.isCurrent(), false);
		assert.strictEqual(JSON.stringify(replacement.snapshot), before);
		assert.ok([...replacement.responseProjection!.byRequest.values()].every(state => !state.inFlight && !state.failure));
		assert.strictEqual(source.beginResponse('replacement', 'permission', 'same').kind, 'started');
	});

});

