			throw new Error(`unexpected service ${String(id)}`);
		});

		await CommandsRegistry.getCommand(SOURCES_REVIEW_OPEN_SELECTED_COMMAND)?.handler?.(accessor);

		assert.strictEqual(marked, 0);
	});
});

